class Gradebook:
    def __init__(self) -> None:
        # assignment name -> (weight, kind)
        self._assignments = {}
        # student -> {assignment name: grade}
        self._grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError(f"Unknown assignment kind: {kind!r}")
        if weight < 0:
            raise ValueError(f"Weight must be non-negative: {weight!r}")
        if name in self._assignments:
            raise ValueError(f"Assignment already exists: {name!r}")
        self._assignments[name] = (float(weight), kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise ValueError(f"Unknown assignment: {assignment!r}")
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade out of scale [2.0, 5.0]: {grade!r}")
        self._grades.setdefault(student, {})[assignment] = float(grade)

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Determine which quiz to drop: the lowest graded quiz, but only
        # if the student has more than one graded quiz.
        quiz_names = [
            name
            for name, (_, kind) in self._assignments.items()
            if kind == "quiz" and name in student_grades
        ]
        dropped = None
        if len(quiz_names) > 1:
            dropped = min(quiz_names, key=lambda n: student_grades[n])

        total_weight = 0.0
        weighted_sum = 0.0
        for name, (weight, _kind) in self._assignments.items():
            if name == dropped:
                continue
            if name not in student_grades:
                continue
            total_weight += weight
            weighted_sum += weight * student_grades[name]

        if total_weight == 0:
            return 0.0

        return round(weighted_sum / total_weight, 2)
